# November 18, 2026: Minnehaha County, South Dakota (Sioux Falls, Garretson, Dell Rapids, Renner, Brandon).
# The first full batch for South Dakota. Sioux quartzite country: a ruined 1881 flour mill and its 1908 power house at the
# falls, quartzite civic buildings and depots, five iron and steel truss bridges of 1895-1908, and two Depression-era
# relief parks built of the same stone. Facts come from Wikipedia (read with tools/wiki_raw.py), the National Register
# nomination texts on NPGallery (read with tools/page.py), HMdb marker texts, the Siouxland Heritage Museums' own pages,
# South Dakota Game, Fish and Parks' pages, and a local news page for the Dell Rapids bathhouse.
from data_b import N
from data_ma import W
BATCH={'key':'sd_xdeo','label':'Minnehaha County, South Dakota: Sioux quartzite, the falls and old truss bridges','added':'2026-11-18 14:56'}
def NOM(n,label='National Register nomination'): return [label,'https://npgallery.nps.gov/NRHP/GetAsset/NRHP/%s_text'%n]
SHM='https://www.siouxlandmuseums.com/?p='
GFP=['SD Game, Fish and Parks: Palisades State Park','https://gfp.sd.gov/parks/detail/palisades-state-park/']
PEL=['SD Game, Fish and Parks: park entrance licence','https://gfp.sd.gov/pel']
ESF=['Experience Sioux Falls: Falls Park','https://www.experiencesiouxfalls.com/fallspark']
FALLS=('Falls Park, a City of Sioux Falls park on North Phillips Avenue; walkways and viewing platforms run along both banks. '
       'The city\'s own park page refused the fetch (HTTP 403), so park hours were not checked. A 2020 news item gives the visitor centre and its 50-foot viewing tower (900 North Phillips Avenue) as 10 a.m. to 5 p.m. daily. ')
PLACES=[
N('queen-bee-mill-ruins','Queen Bee Mill ruins','Sioux Falls','sd','industry','ruins',43.55607,-96.72207,'site','public','walk','','1879–1956',
  'A seven-storey flour mill of Sioux quartzite, quarried on the spot, built 1879 to 1881 under Richard F. Pettigrew to use the power of the Big Sioux falls. It could grind 1,200 barrels a day but water power and wheat both fell short, and it closed in April 1883, less than two years after opening. United Flour Mills ran it again from 1911 to 1916 or 1918 (the sources give both), it was a warehouse from 1937, and a fire in 1956 destroyed it; what was left was pulled down in 1961.',
  'The quartzite foundations of the mill and grain elevator on the east bank of the river in Falls Park, beside the walkways (Wikipedia, citing the Register form; Experience Sioux Falls). Wikipedia also shows a stone turbine house. The 1908 power house that used the mill\'s dam and race stands just to the north.',
  'A seven-storey mill that ran for eighteen months.',
  accn=FALLS,
  links=[W('Queen Bee Mill'),W('Falls Park'),NOM('84003362'),ESF],
  conf='mixed',th=[43.55531,-96.72220],thn='Falls Park lot on the river trail, south of the mill',brick='no'),
N('sioux-falls-light-power-plant','Sioux Falls Light and Power hydroelectric plant','Sioux Falls','sd','industry','standing',43.55714,-96.72161,'exact','public','walk','','1908–',
  'Built in 1908 for the Sioux Falls Light and Power Company, which had bought the idle Queen Bee Mill and the Cascade Mill power plant to make electricity from the falls. It sold power to the public from 1911 and ran the city\'s trolleys; the company became Consumers Power in 1914 and later Northern States Power. Listed on the National Register in 1993.',
  'A quartzite building on a concrete foundation set on a rock outcrop just below the falls. It held three 500-kilowatt generators fed by the old Queen Bee dam and race (Experience Sioux Falls). The machinery was taken out and the building is now the Falls Overlook Cafe, so the public can go in when the cafe is open; cafe hours not checked. Interior fabric not checked.',
  'The mill failed; its dam lit the city.',
  accn=FALLS+'The cafe is a business inside the park.',
  links=[W('Sioux Falls Light and Power Hydro Electric Plant'),ESF],
  th=[43.55914,-96.72293],thn='Falls Park lot, East Falls Park Drive',brick='no'),
N('old-minnehaha-county-courthouse','Old Minnehaha County Courthouse (Old Courthouse Museum)','Sioux Falls','sd','civic','standing',43.55167,-96.72861,'exact','open','walk','','1889–',
  'A Richardsonian Romanesque courthouse of Sioux quartzite with a tall clock tower, designed by Wallace L. Dow. The museum says building began in 1889 and finished in 1893; Wikipedia gives 1890 as the start of county use. It held county business until 1962, was to be pulled down for a parking lot, and was saved by a citizens\' campaign in 1974 and made a museum.',
  'Inside: slate stairs, granite pillars, stained glass windows, tiled fireplaces, the restored second-floor circuit courtroom and law library, and sixteen hallway murals painted 1915 to 1917 by the Norwegian immigrant Ole Running (museum page). Three floors of exhibits; photography allowed.',
  'Sixteen murals that nearly became a parking lot.',
  accn='Siouxland Heritage Museums, Main Avenue and 6th Street. Free. Hours on the museum\'s page: Monday to Friday 8 a.m. to 5 p.m., Thursday to 9 p.m., Saturday 9 to 5, Sunday noon to 5; closed on major holidays. Free two-hour parking west of the building, entered from Dakota Avenue, and metered street parking.',
  links=[W('Old Minnehaha County Courthouse'),['Siouxland Heritage Museums: Old Courthouse Museum',SHM+'111']],
  conf='mixed',th=[43.55182,-96.73082],thn='Lot west of the museum (enter from Dakota Avenue)',brick='no',hours='Monday to Friday 8 a.m. to 5 p.m. (Thursday to 9 p.m.); Saturday 9 to 5; Sunday noon to 5; closed on major holidays'),
N('pettigrew-home-museum','Pettigrew Home and Museum','Sioux Falls','sd','civic','standing',43.54838,-96.7347,'exact','open','walk','','1889–',
  'A Queen Anne house of red brick and Sioux quartzite built in 1889 for Thomas and Jenny McMartin, designed by Wallace L. Dow. Senator Richard F. Pettigrew bought it in 1911, built a museum for his collections on the back that opened in 1925, and left both to the city when he died in 1926.',
  'The house is furnished much as when Pettigrew lived there; guided tours, with galleries on his work and the growing city (museum page). Interior fabric beyond that not checked. It stands in the Cathedral Historic District.',
  accn='Left to the City of Sioux Falls by Pettigrew in 1926 (museum page) and run by Siouxland Heritage Museums, 131 North Duluth Avenue at 8th Street. Free. Hours on the museum\'s page: May 1 to September 30, Monday to Saturday 9 a.m. to 5 p.m. and Sunday noon to 5; October 1 to April 30, daily noon to 5; closed on major holidays. Free street parking on 8th Street and Duluth Avenue; the accessible entrance is on the south side, from the alley.',
  links=[W('Pettigrew Home & Museum'),['Siouxland Heritage Museums: Pettigrew Home & Museum',SHM+'130']],
  brick='some',hours='May 1 to September 30: Monday to Saturday 9 a.m. to 5 p.m., Sunday noon to 5. October 1 to April 30: daily noon to 5. Closed on major holidays'),
N('illinois-central-depot-sioux-falls','Illinois Central passenger depot','Sioux Falls','sd','rail','standing',43.549444,-96.723333,'site','view','walk','stations','1888–',
  'The Illinois Central reached Sioux Falls in December 1887 as the city\'s fourth railroad, and this depot, designed by L. A. Hill, opened in 1888. It is a rare Queen Anne design for a railroad station, built of light purple Sioux quartzite, with the ticket office in the tower room and waiting and baggage rooms either side.',
  'The quartzite depot by the Big Sioux River at 8th Street. What it is used for now, and whether the public can go in, was not checked; interior not checked.',
  accn='By the river at East 8th Street, downtown. Owner and current use not checked: look from the street and the river trail.',
  links=[W('Sioux Falls station (Illinois Central Railroad)'),NOM('83003013')],
  brick='no'),
N('rock-island-depot-sioux-falls','Rock Island depot','Sioux Falls','sd','rail','standing',43.545833,-96.724722,'site','view','walk','stations','1886–1970',
  'Opened in 1886 for the Burlington, Cedar Rapids and Northern, a forerunner of the Rock Island, and served passenger trains until 1970. A Richardsonian Romanesque station of ashlar stone and wood with a side-facing stone gable and an octagonal turret; inside were a waiting room, ticket office and the agent\'s quarters.',
  'The stone depot with its turret at 201 East 10th Street. Current use not checked; interior not checked.',
  accn='201 East 10th Street, downtown. Owner and current use not checked: look from the street.',
  links=[W('Sioux Falls station (Rock Island Line)'),NOM('74001895')],
  brick='no'),
N('sd-state-penitentiary-old-buildings','South Dakota State Penitentiary (1882 buildings)','Sioux Falls','sd','inst','standing',43.5675,-96.724722,'area','view','drive','','1881–',
  'Begun as the Dakota Territory prison in 1881 after Richard Pettigrew won a federal grant for it, designed by Wallace L. Dow and built in 1882; it became the state penitentiary at statehood in 1889. In the 1890s prisoners quarried stone to wall in the yard. Much of the original building survives, much altered. In 2023 the state bought land in Lincoln County for a new men\'s prison to replace it.',
  'Wikipedia says the old prison can be seen from the Big Sioux River. A working prison: look from public streets or the river only.',
  accn='An operating prison of the South Dakota Department of Corrections, North Drive, Sioux Falls. No public access; do not stop at the gates or photograph security features. View from public roads or the river.',
  links=[W('South Dakota State Penitentiary'),NOM('78002565')],
  conf='mixed',brick='?'),
N('cherry-rock-park-bridge','Cherry Rock Park bridge','Sioux Falls','sd','landmark','standing',43.5378,-96.7047,'site','public','walk','','1902–',
  'A 192-foot steel bridge over the Big Sioux River built in 1902 by the C. A. Grinde Company on piers by John Ringdahl, at a park known in the 1890s for its swimming hole. It joins a rare pin-connected Parker through truss (159 feet) to a Pratt pony truss (30 feet). It carried road traffic until 1984, when it became part of the city\'s hiking and biking trails.',
  'The two trusses on stone piers; the Register form (2002) describes plank decking over the north half and a wooden inner railing for walkers.',
  accn='City of Sioux Falls (owner named on the 2002 Register form), on the river trail in Cherry Rock Park. Park hours not checked: the city\'s park pages refused the fetch.',
  links=[NOM('03000499')],
  th=[43.53856,-96.70647],thn='East River Boulevard lot, Cherry Rock Park',brick='no'),
N('old-yankton-bridge-sioux-falls','Old Yankton Bridge (Yankton Trail Bridge)','Sioux Falls','sd','landmark','standing',43.50147,-96.75111,'site','public','walk','','1895–',
  'A pin-connected Parker through truss built in 1895 by S. M. Hewett where the Yankton to Sioux Falls road crossed the Big Sioux River, a ford the HMdb marker says the Yankton Sioux used on the way to the Minnesota pipestone quarries. It replaced an earlier bridge that was declared unsafe in 1895. The Register form calls the type rare for its date; the main span is 149 feet.',
  'The steel truss on tubular steel piers, with a plank deck when it carried wagons (marker). The marker stands in Farm Field Park beside the bridge. Whether the bridge is open to walkers was not checked.',
  accn='Farm Field Park, a City of Sioux Falls park on West 57th Street; the marker is on 57th Street north of Old Yankton Circle (HMdb). Park hours not checked.',
  links=[NOM('99000955'),['HMdb: Yankton Trail Bridge','https://www.hmdb.org/m.asp?m=187262']],
  th=[43.50091,-96.75050],thn='Farm Field Park lot, West 57th Street',brick='no'),
N('iverson-crossing-bridge','Bridge at Iverson Crossing','Brandon','sd','landmark','standing',43.52917,-96.60095,'site','view','drive','','1897–1983',
  'Ole B. Iverson, a Norwegian immigrant, homesteaded at this ford of the Big Sioux in 1868, and stagecoaches from Blue Earth, Minnesota crossed here. Floods took the first bridge in 1895 and its replacement in spring 1897 (the marker says the first was built in 1889). This one, by Hewitt and Company in 1897, is a 370-foot chain of five spans: a 150-foot camel-back Parker through truss with pony-truss approaches. It closed to traffic in 1983.',
  'The trusses on stone and granite piers; the Register form (1996) counts it among three or four pin-connected Parker through trusses built before 1920 in South Dakota. HMdb marker on Iverson Crossing Road.',
  accn='Closed to traffic since 1983; owner not checked. The HMdb marker is on Iverson Crossing Road 0.4 miles west of State Highway 11. Look from the road; do not go onto the bridge.',
  links=[NOM('96000746'),['HMdb: 1897 Bridge at Iverson Crossing','https://www.hmdb.org/m.asp?m=199014']],
  conf='mixed',brick='no'),
N('palisades-bridge-sd','Palisades Bridge','Garretson','sd','landmark','standing',43.68889,-96.51806,'site','public','walk','','1908–',
  'A pin-connected Pratt truss over Split Rock Creek, made in 1908 by the Western Bridge and Construction Company. It replaced a bridge of 1883 that an ice jam destroyed in 1896, and spans the creek between quartzite cliffs. Game, Fish and Parks says a large flour mill, powered by a water wheel on the creek, once stood on the bluff and a town of Palisades grew around it.',
  'The steel truss above the pink quartzite gorge, inside Palisades State Park. Nothing of the mill or town was checked.',
  accn='Palisades State Park, South Dakota Game, Fish and Parks. Use the new entrance at 48422 256th Street. A park entrance licence is required for every vehicle (annual licences and per-vehicle temporary ones; prices on the GFP page). Park hours not checked.',
  links=[W('Palisades Bridge'),W('Palisades State Park'),GFP,PEL],
  th=[43.68923,-96.51876],thn='Split Rock Creek Trail lot, Palisades State Park',brick='?'),
N('split-rock-park-wpa-garretson','Split Rock Park WPA dam, bathhouse and arch bridge','Garretson','sd','civic','standing',43.72056,-96.50194,'site','public','walk','','1910–1936',
  'Depression relief works in Split Rock Park on the north edge of Garretson. In 1933 a quartzite dam was built on the rock footing of an old mill dam on Split Rock Creek, making a lake about half a mile long; the WPA added two culvert bridges (1935), dry-laid retaining walls, a three-bay bathhouse and a four-arch quartzite bridge over Devils Gulch (1936). A Great Northern deck girder railroad bridge of about 1910 crosses the gulch at the east edge. The gulch is tied to the Jesse James legend.',
  'Nine pieces in all (Register form, 2000): the stepped dam, the bathhouse south of it (a gift shop and restrooms in 2000), the arched bridge, the culvert bridges and walls, and the railroad bridge, still in use.',
  'Jesse James\'s gulch, rebuilt by the WPA.',
  accn='City of Garretson park (owner on the 2000 Register form), with a campground. The city\'s page would not load (it shows a browser check), so hours and fees were not checked. The railroad bridge is on an active line: stay off it.',
  links=[NOM('00000827','Register nomination: Split Rock Park District'),NOM('93001309','Register nomination: Split Rock Park Bridge')],
  conf='mixed',brick='no'),
N('campbell-bathhouse-dell-rapids','Gina Smith Campbell Bathhouse','Dell Rapids','sd','civic','standing',43.81992,-96.70217,'exact','public','walk','','1934–',
  'A one-storey Romanesque Revival bathhouse of Sioux quartzite for the bathing beach on the Big Sioux in Dell Rapids City Park, built by Civil Works Administration crews to a design by P. L. Peterson and dedicated on July 4, 1934 to Gina Smith Campbell, who had raised money for the beach. The beach closed in 1960 when a swimming pool was built.',
  'Two arched entries with bullseye openings and stone lintels; the unroofed main room is now covered with fibreglass as a picnic shelter, with two wings either side. While Dennis Daugaard was governor the mayor told the council that the Daugaards had shown interest in helping restore it (Big Sioux Media; the article is undated); whether anything was done was not checked.',
  accn='Dell Rapids City Park, on the river. Park hours not checked.',
  links=[W('Gina Smith Campbell Bathhouse'),['Big Sioux Media: Bathhouse in Dell Rapids could see updates','https://bigsiouxmedia.com/bathhouse-in-dell-rapids-could-see-updates']],
  th=[43.81901,-96.70601],thn='Ball park lot, South Garfield Avenue',brick='no'),
N('dell-rapids-fourth-street','Dell Rapids historic Fourth Street','Dell Rapids','sd','town','standing',43.82333,-96.71,'area','view','walk','','1885–1934',
  'Dell Rapids grew on the quarries: Sioux quartzite ashlar and paving block went out by rail from the 1880s. A fire destroyed the whole south side of the main street, and the rebuilding, mostly between 1888 and 1901, was in quarry-faced quartzite. The historic district covers both sides of East Fourth Street from 335 to 536.',
  'Two-storey quartzite business blocks: the 1889 First National Bank with its corner tower (501 East Fourth), the 1885 Peoples State Bank with round-arched openings, the Augustine-Johnson Block (1888), the Smith Block (1888) with dark brick round its openings, an Opera House that kept its second-floor theatre, and the 1934 Art Deco Dells Theatre (Register form, 1978). What is in each building now was not checked.',
  'A whole main street cut from one quarry.',
  accn='Public street; shops are private. Look from the sidewalk.',
  links=[W('Dell Rapids, South Dakota'),NOM('78002563','Register nomination: Dell Rapids Historic District')],
  brick='?'),
N('st-peters-lutheran-dell-rapids',"St. Peter's Lutheran Church",'Dell Rapids','sd','worship','standing',43.82611,-96.71028,'site','view','walk','','1902–',
  'A Romanesque Revival church built in 1902 of Sioux quartzite quarried locally.',
  'The quartzite exterior. Interior not checked; whether it is open outside services not checked.',
  accn='A church: view from the street.',
  links=[W("St. Peter's Lutheran Church (South Dakota)")],
  brick='no'),
N('renner-lutheran-sanctuary','Renner Lutheran Sanctuary (Nidaros church)','Renner','sd','worship','standing',43.64559,-96.71639,'site','view','drive','','1878–',
  'The congregation of Norwegian settlers first met in the sod house of John and Kirsti Thompson. A windstorm destroyed their new prairie church in April 1878 and the present church was built from its wreckage, with a shorter steeple than the one blamed for its fall. The altar dates from 1886. In 1939 the building was moved to Renner.',
  'A white clapboard "country church Gothic" building on a high rock-faced concrete foundation, with red quatrefoil openings over the entrance and in the steeple (Register form). The 1886 altar is still in the sanctuary (Wikipedia). Interior otherwise not checked.',
  accn='A church: view from the street. Opening outside services not checked.',
  links=[W('Renner Lutheran Church'),NOM('80003729')],
  brick='no'),
]
